    await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
    await expect(pg_wes.getByTestId("header-due-total")).toHaveText("2.00");
    await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
    expect(await ui.editPerson(pg_wes, p_cam, {"grade": "B"})).toBe(true);
    expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "10.00"})).toBe(true);
    expect(await ui.pasteClaims(pg_wes, "Ada,0.40,,\nAda,10.35,2026-03-01,a, b\nCam,10.35,2026-03-05,")).toBeNull();
    await ui.refresh(pg_vic);
